def P2(cs, tail, n):
    a = ADJm(*cs)
    return f" – {KAA} {a} {RC}। {PK} {KAA} {a} {RK}। {APO} {a} {RCKU}। {APO} {tail}। ({n})"


def P3(cs, tail, n):
    a = ADJm(*cs)
    return (f" – {ONEaa} {B1} तीन समूह और {a} {RC}… दो समूहों… {PK} {ONEaa} {B1} तीन समूह और {a} {RK}… "
            f"दो समूहों… {APO} {a} {RCKU}। {APO} {tail}। ({n})")


def P4(cs, tail, n, extra=""):
    a = ADJm(*cs)
    return f" – {KMB} {a} {RC}। {PK} {KMB} {a} {RK}।{extra} {MAP} {a} {RCKU}। {PA} {tail}। ({n})"


