    PN(D(as_), DT(aa), "atthi") + f" – सह-उत्पत्ति, पूर्व-उत्पत्ति। सह-उत्पत्ति – {aso} महाभूत {aao}, {DCKU} {I('atthi', 'mp')} (पहचान-रहित प्राणियों तक विस्तार करना चाहिए)। पूर्व-उत्पत्ति – आँख… शरीर, ध्वनियों… स्पर्शों को अनित्य के रूप में… उदासी उत्पन्न होती है, आँख का इंद्रिय-क्षेत्र आँख की चेतना के लिए… स्पर्श का इंद्रिय-क्षेत्र शरीर की चेतना के लिए {I('atthi', 'ms')}। (3)",
    "(शेष चार प्रश्नों का विस्तार करना चाहिए। निर्भरता के खंड में सह-उत्पत्ति-कारण के समान, बिना किसी अंतर के।) (7)",
    PN(D(aa), DT(aa), "atthi") + f" – सह-उत्पत्ति, पूर्व-उत्पत्ति, पश्चात्-उत्पत्ति, आहार, क्षमता। सह-उत्पत्ति – {ONE(aa, 'm')} तीन समूहों के लिए और {aao}, {DCR} {I('atthi', 'ms')}। दो समूह… {PK}… जल तत्व {aao}, {DCKU}… जल तत्व स्त्रीत्व की क्षमता के लिए… और कौर-कौर खाए जाने वाले भोजन के लिए {I('atthi', 'ms')}। {BAU} जल तत्व {aao}, {DKU} {I('atthi', 'ms')}। पूर्व-उत्पत्ति – {RUPAS} अनित्य के रूप में… उदासी उत्पन्न होती है, आधार {KH(aa)} के लिए {I('atthi', 'ms')}। पश्चात्-उत्पत्ति – {KN(aa)} पहले उत्पन्न इस {aao} शरीर के लिए {I('atthi', 'mp')}। {KABA} इस {aao} शरीर के लिए {I('atthi', 'ms')}। {RJI} {aao}, {DKR} {I('atthi')} (इस तरह शेष छह प्रश्नों का विश्लेषण करना चाहिए। सह-उत्पत्ति, पश्चात्-उत्पत्ति, आहार और क्षमता भी करने चाहिए)। (7)",
    PN(DP(ss, aa), DT(aa), "atthi", "fp") + f"। पूर्व-उत्पत्ति – दृश्य रूप का इंद्रिय-क्षेत्र और आधार {KH(aa)} के लिए {I('atthi', 'mp')}। (1)",
    PN(DP(as_, aa), DT(ss), "atthi", "fp") + f" – {KN(aa)} और महाभूत {sso}, {DCR} {I('atthi', 'mp')}। {PK}… (संक्षिप्त, और पहचान-रहित प्राणियों में भी करना चाहिए)। (1)",
